// The affiliate payment structure as published to affiliates by the founder.
// ONE source of truth: the dashboard's "Your terms" card (GET
// /api/affiliate/terms) and the payment-structure resource document
// (data/affiliate-resources/payment-structure.md, generated by
// scripts/generateAffiliatePaymentStructureDoc.ts) both read this constant.
// Do not invent numbers here — personal rates and bonus rungs live in each
// affiliate's agreement (Affiliate.* columns + agreementNote).

export interface PaymentStream {
  key: 'consumer_pro' | 'trainer' | 'campaign' | 'ugc';
  name: string;
  whatYouEarn: string;
  howLong: string;
}

export interface BonusLadder {
  key: 'growth' | 'durability' | 'fast_start';
  name: string;
  description: string;
}

