/** Render the structure as the markdown resource document. */
export function renderPaymentStructureMarkdown(s = AFFILIATE_PAYMENT_STRUCTURE): string {
  const esc = (t: string) => t.replace(/\|/g, '\\|');
  const lines: string[] = [];
  lines.push(`# ${s.title}`, '');
  lines.push(
    `Axiom pays affiliates through four streams, all paid monthly in ${s.currency}.`,
    '',
  );
  lines.push('## How you get paid', '');
  for (const h of s.howYouGetPaid) lines.push(`- ${h}`);
  lines.push('');
  lines.push('## The four streams', '');
  lines.push('| # | Stream | What you earn | How long |', '|---|---|---|---|');
  s.streams.forEach((st, i) => {
    lines.push(`| ${i + 1} | ${esc(st.name)} | ${esc(st.whatYouEarn)} | ${esc(st.howLong)} |`);
  });
  lines.push('', `${s.trainerPlans}`, '');
  lines.push('## Bonuses', '', s.bonusesIntro, '');
  for (const b of s.bonuses) lines.push(`- **${b.name}**: ${b.description}`);
  lines.push('', '## Payment rules', '');
  for (const r of s.paymentRules) lines.push(`- ${r}`);
  lines.push('', '## Your personal terms', '', s.personalTermsNote + ' Trainer rate, campaign rate, per-video fee and any agreement notes are shown there.', '');
  return lines.join('\n');
}
